ALTER TABLE users ADD COLUMN IF NOT EXISTS password_hash text;
ALTER TABLE users ADD COLUMN IF NOT EXISTS email_verified boolean NOT NULL DEFAULT false;
ALTER TABLE users ADD COLUMN IF NOT EXISTS settings jsonb NOT NULL DEFAULT '{}';
ALTER TABLE users ADD COLUMN IF NOT EXISTS totp_envelope jsonb;
ALTER TABLE credentials ADD COLUMN IF NOT EXISTS envelope_version integer NOT NULL DEFAULT 1;
ALTER TABLE analyses ADD COLUMN IF NOT EXISTS mode text NOT NULL DEFAULT 'quick';
ALTER TABLE analyses ADD COLUMN IF NOT EXISTS expires_at timestamptz;
ALTER TABLE signals ADD COLUMN IF NOT EXISTS setup jsonb;
ALTER TABLE signals ADD COLUMN IF NOT EXISTS last_evaluated_at timestamptz;
ALTER TABLE paper_accounts ADD COLUMN IF NOT EXISTS initial_balance numeric(30,12) NOT NULL DEFAULT 10000;
ALTER TABLE paper_orders ADD COLUMN IF NOT EXISTS venue text NOT NULL DEFAULT 'binance';
ALTER TABLE paper_orders ADD COLUMN IF NOT EXISTS market text NOT NULL DEFAULT 'spot';
ALTER TABLE paper_orders ADD COLUMN IF NOT EXISTS closed_at timestamptz;
ALTER TABLE paper_orders ADD COLUMN IF NOT EXISTS close_price numeric(30,12);
ALTER TABLE paper_orders ADD COLUMN IF NOT EXISTS pnl numeric(30,12);
ALTER TABLE journal_entries ADD COLUMN IF NOT EXISTS side text NOT NULL DEFAULT 'LONG';
ALTER TABLE journal_entries ADD COLUMN IF NOT EXISTS opened_at timestamptz DEFAULT now();
CREATE TABLE IF NOT EXISTS auth_tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind text NOT NULL,token_hash text UNIQUE NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,title_key text NOT NULL,data jsonb NOT NULL,read boolean DEFAULT false,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS schedules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,config jsonb NOT NULL,interval_minutes integer NOT NULL CHECK(interval_minutes>=15),next_run timestamptz NOT NULL,enabled boolean DEFAULT true,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS chat_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,symbol text NOT NULL,role text NOT NULL,content text NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS api_rate_limits(bucket text PRIMARY KEY, count integer NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS daily_budgets(user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,day date NOT NULL,used numeric(18,8) DEFAULT 0,reserved numeric(18,8) DEFAULT 0,analyses integer DEFAULT 0,PRIMARY KEY(user_id,day));
CREATE INDEX IF NOT EXISTS notifications_user_idx ON notifications(user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS schedules_due_idx ON schedules(next_run) WHERE enabled;
ALTER TABLE analyses ADD COLUMN IF NOT EXISTS request_config jsonb NOT NULL DEFAULT '{}';
ALTER TABLE analyses ADD COLUMN IF NOT EXISTS error_code text;
ALTER TABLE users ADD COLUMN IF NOT EXISTS push_subscription jsonb;
CREATE TABLE IF NOT EXISTS imported_trades(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,venue text NOT NULL,symbol text NOT NULL,trade_id text NOT NULL,data jsonb NOT NULL,created_at timestamptz DEFAULT now(),UNIQUE(user_id,venue,symbol,trade_id));
CREATE TABLE IF NOT EXISTS journal_attachments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,journal_id uuid NOT NULL REFERENCES journal_entries(id) ON DELETE CASCADE,mime_type text NOT NULL,bytes bytea NOT NULL,created_at timestamptz DEFAULT now(),CHECK(octet_length(bytes)<=2000000));
ALTER TABLE paper_accounts ADD COLUMN IF NOT EXISTS peak_equity numeric(30,12) NOT NULL DEFAULT 10000;
CREATE TABLE IF NOT EXISTS billing_events(id text PRIMARY KEY,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE subscriptions ADD COLUMN IF NOT EXISTS event_timestamp bigint NOT NULL DEFAULT 0;
ALTER TABLE analyses ADD COLUMN IF NOT EXISTS started_at timestamptz;
ALTER TABLE analyses ADD COLUMN IF NOT EXISTS reservation_usd numeric(18,8) NOT NULL DEFAULT 0.5;
ALTER TABLE backtests ADD COLUMN IF NOT EXISTS started_at timestamptz;
